CAT = "dktrHours"; SEG = "HRS"
# Afsnit 6.3 to 6.5: driving and rest times (Reg. 561/2006 as taught in the plan), tachograph use,
# haulage permits and the driver CPC.
Q = [
("You drove 10 hours on Monday. On how many more days this week may you drive 10 hours?",
 "One more day", ["Two more days", "None at all", "Four more days"],
 "Daily driving may be extended from 9 to 10 hours at most twice a week. Monday used one, so one more 10-hour day is left."),
("Last week you drove 50 hours. What is the most you may drive this week?",
 "40 hours", ["56 hours", "46 hours", "34 hours"],
 "Weekly driving may be up to 56 hours, but two consecutive weeks may not add up to more than 90 hours. 90 minus 50 leaves 40."),
("You and a colleague share the driving for the whole trip. What daily rest does each of you need within 30 hours?",
 "At least 9 hours", ["At least 11 hours", "At least 7 hours", "At least 12 hours"],
 "When there is more than one driver throughout (apart from the first hour), each must have a daily rest of at least 9 consecutive hours within a 30-hour period."),
("You took a 15-minute break after 2 hours of driving. What break do you still need by the time you reach 4.5 hours?",
 "At least 30 minutes", ["At least 15 minutes", "At least 45 minutes", "No further break"],
 "The 45-minute break can be split into at least 15 minutes followed by at least 30 minutes. The order cannot be swapped."),
("Two of you drive in turns. May the one not driving take the 45-minute break while the lorry moves?",
 "Yes, if not assisting", ["No, only when parked", "Only after midnight", "Only on motorways"],
 "With more than one driver, the break may be taken in a moving vehicle provided the driver taking it does not assist the driver who is driving."),
("You will operate a lorry-mounted crane rated over 8 tonne metres. What do you need besides your licence?",
 "A crane operator certificate", ["An ADR certificate", "A haulage permit", "Nothing more"],
 "Drivers who operate lorry-mounted cranes with a capacity of more than 8 tonne metres must hold a certificate for special training. The same applies to mobile cranes."),
("Since your last weekly rest you have already cut your daily rest to 9 hours three times. How long must tonight's daily rest be?",
 "At least 11 hours", ["At least 9 hours", "At least 10 hours", "At least 7 hours"],
 "The daily rest may be reduced to 9 hours no more than three times between weekly rests. After that you need a regular daily rest of at least 11 hours."),
("Your last weekly rest ended on Wednesday at 22:00. By when must your next weekly rest start at the latest?",
 "Tuesday at 22:00", ["Monday at 22:00", "Wednesday at 22:00", "Thursday at 22:00"],
 "A weekly rest must start no later than the end of six consecutive 24-hour periods after the previous one ended. Six days from Wednesday 22:00 is Tuesday 22:00."),
("You took a reduced weekly rest of 24 hours. You will add the compensation to a 9-hour rest. How long must that combined rest be at least?",
 "30 hours", ["21 hours", "45 hours", "24 hours"],
 "The 21 hours short of a 45-hour rest must be made up within three weeks, attached to another rest of at least 9 hours: 21 plus 9 makes 30 hours."),
("Where may you take a daily rest away from your base?",
 "In the parked cab with a bed", ["In the cab while a colleague drives", "In the passenger seat", "Only at a hotel"],
 "Daily rests and reduced weekly rests away from home may be taken in the vehicle if it has suitable sleeping facilities for each driver and is stationary."),
("You want to take a regular weekly rest on a ferry. When is that allowed?",
 "On a trip of 8 hours or more", ["On any ferry crossing", "Never on a ferry", "Only on Danish ferries"],
 "The ferry and train exception covers regular weekly rests only for crossings of 8 hours or more, and only if you have a sleeper cabin on board."),
("Your driver card is stolen during a trip. How can your activities be recorded?",
 "On tachograph printouts", ["On a colleague's card", "In your phone's notes", "They need not be recorded"],
 "In special cases such as a damaged or stolen card, a printout from the digital tachograph can be used to record the driver's activities. You may only ever use your own card."),
("Which tachograph records must you carry while driving?",
 "Today's and the last 56 days'", ["Today's and the last 28 days'", "Only today's records", "Today's and the last 7 days'"],
 "Charts, card data and any manual records or printouts for the current day and the previous 56 calendar days must be carried and shown to inspectors on request."),
("How long may an analogue tachograph chart stay in the tachograph at most?",
 "24 hours", ["12 hours", "48 hours", "One week"],
 "A chart may normally only be changed at the end of the daily working period, and it may stay in the tachograph for at most 24 hours."),
("You will carry goods for other firms for payment in a lorry over 3.5 tonnes. Who issues the permit you need?",
 "Færdselsstyrelsen", ["Motorstyrelsen", "The local council", "The police"],
 "Anyone established in Denmark who carries goods for hire with a vehicle or combination over 3.5 tonnes needs a permit from Færdselsstyrelsen. Own-account lorries are registered with Motorstyrelsen."),
("A professional lorry driver holds the driver CPC. How often is periodic training needed?",
 "Every five years", ["Every three years", "Every ten years", "Every two years"],
 "Professional lorry drivers need the initial CPC qualification and then periodic training every five years, lasting at least five days."),
]
